#!/usr/bin/env python3
"""Drill N cards on a running hashcards server, grading each 'Good'."""
import sys, urllib.request, urllib.parse, re

PORT = sys.argv[1] if len(sys.argv) > 1 else "8303"
N = int(sys.argv[2]) if len(sys.argv) > 2 else 5
GRADE = sys.argv[3] if len(sys.argv) > 3 else "Good"
BASE = f"http://127.0.0.1:{PORT}/"

def get():
    return urllib.request.urlopen(BASE).read().decode()

def post(action):
    data = urllib.parse.urlencode({"action": action}).encode()
    return urllib.request.urlopen(BASE, data=data).read().decode()

n = 0
while n < N:
    h = get()
    if "Reveal" not in h and "Forgot" not in h:
        print("no more cards / done page")
        break
    if "Reveal" in h:
        post("Reveal")
    h = get()
    if "Forgot" not in h:
        print("unexpected: no grade buttons")
        break
    post(GRADE)
    n += 1
print("graded", n)
